from collections import defaultdict
from itertools import combinations


class Solution:
    def checkWays(self, pairs: List[List[int]]) -> int:
        adj = defaultdict(set)
        for x, y in pairs:
            adj[x].add(y)
            adj[y].add(x)

        def count(rem, prev):
            if not rem:
                return 1
            total = 0
            elems = sorted(rem)
            for size in range(1, len(elems) + 1):
                for layer in combinations(elems, size):
                    layer = set(layer)
                    rest = rem - layer
                    ok = not any(b in adj[a] for a, b in combinations(sorted(layer), 2))
                    if ok:
                        ok = all(v in adj[u] for u in layer for v in prev)
                    if ok:
                        ok = all(v in adj[u] for u in layer for v in rest)
                    if ok:
                        total += count(rest, layer)
            return total

        nodes = frozenset(adj)
        roots = [u for u in nodes if len(adj[u]) == len(nodes) - 1]
        if not roots:
            return 0
        total = 0
        for r in roots:
            rem = nodes - {r}
            total += count(rem, frozenset({r}))
            if total >= 2:
                break
        return min(total, 2)

