class Solution {
    vector<unordered_set<int>> adj = vector<unordered_set<int>>(501);

    long long count(vector<int>& rem, vector<int>& anc) {
        if (rem.empty()) return 1;
        int m = rem.size();
        long long total = 0;
        for (long long mask = 1; mask < (1LL << m); ++mask) {
            bool ok = true;
            for (int i = 0; ok && i < m; ++i) {
                if (!((mask >> i) & 1)) continue;
                for (int j = 0; ok && j < m; ++j)
                    if (!((mask >> j) & 1) && !adj[rem[i]].count(rem[j])) ok = false;
                for (int a : anc)
                    if (!adj[rem[i]].count(a)) ok = false;
            }
            if (!ok) continue;
            vector<int> rest, nextAnc = anc;
            for (int i = 0; i < m; ++i)
                ((mask >> i) & 1 ? nextAnc : rest).push_back(rem[i]);
            total += count(rest, nextAnc);
            if (total >= 2) return total;
        }
        return total;
    }

public:
    int checkWays(vector<vector<int>>& pairs) {
        set<int> nodes;
        for (auto& p : pairs) {
            nodes.insert(p[0]);
            nodes.insert(p[1]);
            adj[p[0]].insert(p[1]);
            adj[p[1]].insert(p[0]);
        }
        int n = nodes.size();
        vector<int> all(nodes.begin(), nodes.end());
        long long total = 0;
        for (int r : all) {
            if ((int)adj[r].size() != n - 1) continue;
            vector<int> rem, anc{r};
            for (int u : all)
                if (u != r) rem.push_back(u);
            total += count(rem, anc);
            if (total >= 2) break;
        }
        if (total == 0) return 0;
        return total > 1 ? 2 : 1;
    }
};

