import java.util.*;

class Solution {
    private Map<Integer, Set<Integer>> adj = new HashMap<>();
    private int total;

    private void count(List<Integer> rem, List<Integer> anc) {
        if (rem.isEmpty()) {
            total++;
            return;
        }
        int m = rem.size();
        for (long mask = 1; mask < (1L << m); mask++) {
            boolean ok = true;
            for (int i = 0; ok && i < m; i++) {
                if (((mask >> i) & 1) == 0) continue;
                for (int j = 0; ok && j < m; j++)
                    if (((mask >> j) & 1) == 0 && !adj.get(rem.get(i)).contains(rem.get(j))) ok = false;
                for (int a : anc)
                    if (!adj.get(rem.get(i)).contains(a)) ok = false;
            }
            if (!ok) continue;
            List<Integer> rest = new ArrayList<>(), nextAnc = new ArrayList<>(anc);
            for (int i = 0; i < m; i++)
                if (((mask >> i) & 1) == 1) nextAnc.add(rem.get(i));
                else rest.add(rem.get(i));
            count(rest, nextAnc);
            if (total >= 2) return;
        }
    }

    public int checkWays(int[][] pairs) {
        TreeSet<Integer> nodes = new TreeSet<>();
        for (int[] p : pairs) {
            nodes.add(p[0]);
            nodes.add(p[1]);
            adj.computeIfAbsent(p[0], k -> new HashSet<>()).add(p[1]);
            adj.computeIfAbsent(p[1], k -> new HashSet<>()).add(p[0]);
        }
        total = 0;
        int n = nodes.size();
        boolean anyRoot = false;
        for (int r : nodes) {
            if (adj.get(r).size() != n - 1) continue;
            anyRoot = true;
            List<Integer> rem = new ArrayList<>(), anc = new ArrayList<>(List.of(r));
            for (int u : nodes)
                if (u != r) rem.add(u);
            count(rem, anc);
            if (total >= 2) break;
        }
        if (!anyRoot || total == 0) return 0;
        return total > 1 ? 2 : 1;
    }
}

