var checkWays = function(pairs) {
    const adj = new Map();
    const ensure = (u) => {
        if (!adj.has(u)) adj.set(u, new Set());
        return adj.get(u);
    };
    const nodes = new Set();
    for (const [x, y] of pairs) {
        nodes.add(x);
        nodes.add(y);
        ensure(x).add(y);
        ensure(y).add(x);
    }
    let total = 0;
    const count = (rem, anc) => {
        if (rem.length === 0) {
            total++;
            return;
        }
        const m = rem.length;
        for (let mask = 1; mask < 2 ** m; mask++) {
            let ok = true;
            for (let i = 0; ok && i < m; i++) {
                if (!((mask >> i) & 1)) continue;
                for (let j = 0; ok && j < m; j++)
                    if (!((mask >> j) & 1) && !adj.get(rem[i]).has(rem[j])) ok = false;
                for (const a of anc)
                    if (!adj.get(rem[i]).has(a)) ok = false;
            }
            if (!ok) continue;
            const rest = [], nextAnc = [...anc];
            for (let i = 0; i < m; i++)
                if ((mask >> i) & 1) nextAnc.push(rem[i]);
                else rest.push(rem[i]);
            count(rest, nextAnc);
            if (total >= 2) return;
        }
    };
    const all = [...nodes].sort((a, b) => a - b);
    const n = all.length;
    let anyRoot = false;
    for (const r of all) {
        if (adj.get(r).size !== n - 1) continue;
        anyRoot = true;
        count(all.filter((u) => u !== r), [r]);
        if (total >= 2) break;
    }
    if (!anyRoot || total === 0) return 0;
    return total > 1 ? 2 : 1;
};

